#!/usr/bin/env python3
"""
Round 137b (culprits-tiles-more), 2 October 2026.

fish_stocks.py (new): RAM Legacy fish stocks, country by country.
lpi_populations.py (new): the Living Planet Database populations, from the owner's download in lpi/download/.

Writes each file only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/fish_stocks.py': '', 'scripts/lpi_populations.py': '', 'lpi/download/README.md': ''}


def main():
    for path, b64 in FILES.items():
        p = pathlib.Path(path)
        data = base64.b64decode(b64)
        if p.exists() and p.read_bytes() == data:
            print(f"round137b_tiles: {path} already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print(f"round137b_tiles: wrote {path}")


if __name__ == "__main__":
    main()
